Can_Per_Node* can_per_node_free_create( void ) 
{
	Can_Per_Node *can_per_node = (Can_Per_Node*)os_mem_request( sizeof( struct s_Can_Per_Node ) ) ;

	if( can_per_node )
    {            
        out_set( (Out)(&(can_per_node->can_per_obj)) , (Out_Func)can_per_tx );                 
	} 

	return can_per_node ;         
}

